// OnConflict allows configuring the `ON CONFLICT` / `ON DUPLICATE KEY` clause
// of the `INSERT` statement. For example:
//
//	client.IntakeRequest.CreateBulk(builders...).
//		OnConflict(
//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.IntakeRequestUpsert) {
//			SetTenantID(v+v).
//		}).
//		Exec(ctx)
func (_c *IntakeRequestCreateBulk) OnConflict(opts ...sql.ConflictOption) *IntakeRequestUpsertBulk {
	_c.conflict = opts
	return &IntakeRequestUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
// as conflict target. Using this option is equivalent to using:
//
//	client.IntakeRequest.Create().
//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (_c *IntakeRequestCreateBulk) OnConflictColumns(columns ...string) *IntakeRequestUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &IntakeRequestUpsertBulk{
		create: _c,
	}
}

// IntakeRequestUpsertBulk is the builder for "upsert"-ing
// a bulk of IntakeRequest nodes.
type IntakeRequestUpsertBulk struct {
	create *IntakeRequestCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.IntakeRequest.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//		).
//		Exec(ctx)
func (u *IntakeRequestUpsertBulk) UpdateNewValues() *IntakeRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.TenantID(); exists {
				s.SetIgnore(intakerequest.FieldTenantID)
			}
			if _, exists := b.mutation.ActorID(); exists {
				s.SetIgnore(intakerequest.FieldActorID)
			}
			if _, exists := b.mutation.Channel(); exists {
				s.SetIgnore(intakerequest.FieldChannel)
			}
			if _, exists := b.mutation.Operation(); exists {
				s.SetIgnore(intakerequest.FieldOperation)
			}
			if _, exists := b.mutation.IdempotencyKey(); exists {
				s.SetIgnore(intakerequest.FieldIdempotencyKey)
			}
			if _, exists := b.mutation.RequestDigest(); exists {
				s.SetIgnore(intakerequest.FieldRequestDigest)
			}
			if _, exists := b.mutation.DigestVersion(); exists {
				s.SetIgnore(intakerequest.FieldDigestVersion)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(intakerequest.FieldCreatedAt)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.IntakeRequest.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *IntakeRequestUpsertBulk) Ignore() *IntakeRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *IntakeRequestUpsertBulk) DoNothing() *IntakeRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the IntakeRequestCreateBulk.OnConflict
// documentation for more info.
func (u *IntakeRequestUpsertBulk) Update(set func(*IntakeRequestUpsert)) *IntakeRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&IntakeRequestUpsert{UpdateSet: update})
	}))
	return u
}

